package com.codeguardian.repository; import com.codeguardian.entity.RolePermission; import org.springframework.data.jpa.repository.*; import org.springframework.stereotype.Repository; import java.util.List; @Repository public interface RolePermissionRepository extends JpaRepository<RolePermission,Long>{List<RolePermission> findByRoleId(Long id); List<RolePermission> findByPermissionId(Long id); void deleteByRoleId(Long id); void deleteByPermissionId(Long id); boolean existsByRoleIdAndPermissionId(Long r,Long p); @Query("select p.code from RolePermission rp join Permission p on rp.permissionId=p.id where rp.roleId=:roleId") List<String> findPermissionCodesByRoleId(Long roleId);}
